extract.source:
type Tag = {k:'i';value:number}|{k:'c';value:string};
 type Int = Extract<Tag,{k:'i'}>;
 type Payload = Int['value'];
 export function read(x:Int):Payload {return x.value;}

recursive.source:
type Tree = {k:'leaf';value:number} | {k:'branch';left:Tree;right:Tree};
 interface Program {root:Tree;}
 export function total(x:Tree):number {if(x.k==='leaf') return x.value; return total(x.left)+total(x.right);}

tag.source:
type Tag = {k: 'i'; value: number} | {k: 'c'; value: string};
 export function tag(x: Tag): string { return x.k; }
 export function read(x: Tag): string {if(x.k==='i') return String(x.value); return x.value;}
